#!/usr/bin/env node

const { spawn } = require('child_process');
const path = require('path');
const os = require('os');
const fs = require('fs');

function getPlatform() {
    const platform = os.platform();
    if (platform === 'win32') return 'windows';
    if (platform === 'darwin') return 'macos';
    if (platform === 'linux') return 'linux';
    return null;
}

function getBinaryDir() {
    return path.join(__dirname, '..', 'binaries', getPlatform());
}

function getBinaryPath() {
    const dir = getBinaryDir();
    const name = os.platform() === 'win32' ? 'hoolius.exe' : 'hoolius';
    return path.join(dir, name);
}

function installCheck() {
    const binaryPath = getBinaryPath();
    if (fs.existsSync(binaryPath)) {
        process.exit(0);
    }

    const platform = getPlatform();
    console.error('');
    console.error('  Hoolius binary not found for ' + platform + '.');
    console.error('');
    console.error('  To build it from source:');
    console.error('    cd ' + path.relative(process.cwd(), path.join(__dirname, '..')));
    console.error('    make');
    console.error('    cp hoolius ' + path.relative(process.cwd(), getBinaryDir()));
    console.error('');
    process.exit(1);
}

function run() {
    const binaryPath = getBinaryPath();

    if (!fs.existsSync(binaryPath)) {
        console.error('Error: Hoolius binary not found at ' + binaryPath);
        console.error('Run "make" to build it first.');
        process.exit(1);
    }

    const args = process.argv.slice(2);
    const child = spawn(binaryPath, args, {
        stdio: 'inherit'
    });

    child.on('exit', function (code) {
        process.exit(code);
    });

    child.on('error', function (err) {
        console.error('Failed to launch Hoolius: ' + err.message);
        process.exit(1);
    });
}

function main() {
    if (process.argv.indexOf('--install-check') !== -1) {
        installCheck();
        return;
    }

    const platform = getPlatform();
    if (!platform) {
        console.error('Unsupported platform: ' + os.platform());
        process.exit(1);
    }

    run();
}

main();
